CREATE TABLE oauth_states(state_hash VARCHAR(255) PRIMARY KEY, session_hash VARCHAR(255) NOT NULL, nonce VARCHAR(255) NOT NULL, verifier VARCHAR(255) NOT NULL, expires_at BIGINT NOT NULL,FOREIGN KEY (session_hash) REFERENCES sessions(token_hash) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE oauth_identities(id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, provider VARCHAR(255) NOT NULL, subject VARCHAR(255) NOT NULL, UNIQUE(provider,subject),FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
